// ensureLoaded performs the one automatic load attempt. A later explicit
// call can still succeed with a different path.
func ensureLoaded() {
	loadMu.Lock()
	defer loadMu.Unlock()
	if loadedBindings.Load() != nil || automaticLoadAttempted {
		return
	}
	automaticLoadAttempted = true
	automaticLoadError = loadLibraryLocked("")
}

func bindings() *nativeBindings {
	value := loadedBindings.Load()
	if value == nil {
		ensureLoaded()
		value = loadedBindings.Load()
	}
	if value == nil {
		panic(automaticLoadError)
	}
	return value
}

// LastErrorMessage returns the most recent native panic message for this binding.
func LastErrorMessage() string {
	p := bindings().lastError()
	if p == nil {
		return ""
	}
	length := 0
	for *(*byte)(unsafe.Add(p, length)) != 0 {
		length++
	}
	return string(unsafe.Slice((*byte)(p), length))
}

// PanicMessage returns the message of the native panic a status code of -256 or below names.
func PanicMessage(code int32) string {
	p := bindings().panicMessage(code)
	if p == nil {
		return ""
	}
	length := 0
	for *(*byte)(unsafe.Add(p, length)) != 0 {
		length++
	}
	return string(unsafe.Slice((*byte)(p), length))
}

// zigoCallFrame holds one direct call's arguments and the slots its out
// parameters are written to. purego.SyscallN lets its argument slice escape,
// and native code must not be handed an address on a goroutine stack that a
// callback could grow and move, so both live in a pooled frame on the heap.
type zigoCallFrame struct {
	args [8]uintptr
	out  [2]uint64
}

var zigoCallFrames = sync.Pool{New: func() any { return new(zigoCallFrame) }}

// zigoEscapeSink is never written. zigoEscape only has to look as though it
// might store its argument, so that the compiler keeps what a pointer handed
// to native code points at on the heap, as a call through RegisterFunc did.
var zigoEscapeSink struct {
	enabled bool
	p       unsafe.Pointer
}

func zigoEscape(p unsafe.Pointer) {
	if zigoEscapeSink.enabled {
		zigoEscapeSink.p = p
	}
}

